} elseif($page==='queue') {
    $pending=all("SELECT ev.*,p.title project_title,a.title activity_title FROM evidence ev JOIN projects p ON p.id=ev.project_id JOIN activities a ON a.id=ev.activity_id WHERE p.manager_id=? AND ev.review_status IN ('unique_ready','pending_review') ORDER BY ev.max_similarity DESC,ev.uploaded_at DESC",[uid()]);
    $history=all("SELECT ev.*,p.title project_title,a.title activity_title FROM evidence ev JOIN projects p ON p.id=ev.project_id JOIN activities a ON a.id=ev.activity_id WHERE p.manager_id=? AND ev.review_status IN ('approved','rejected') ORDER BY ev.reviewed_at DESC LIMIT 30",[uid()]);
    page_start('AI review queue',true);
    echo '<div class="page-head"><div><span class="eyebrow">AI image Recognition</span><h1>Image review queue</h1><p>Approve unique evidence, examine similarity alerts and keep an auditable record of decisions.</p></div><a class="btn" href="'.url('evidence').'">+ Upload evidence</a></div>';
    if(!$pending) echo '<div class="content-card empty"><span>✓</span><h2>You’re all caught up</h2><p>There are no images waiting for a decision.</p></div>';
    else foreach($pending as $ev) {
        $flag=$ev['review_status']==='pending_review';
        echo '<article class="review-card" id="evidence-'.(int)$ev['id'].'"><div class="review-picture"><img src="image.php?id='.(int)$ev['id'].'" alt="Uploaded project photo"></div><div class="review-details"><span class="eyebrow">'.e($ev['project_title']).' · '.e($ev['activity_title']).'</span><h2>'.($flag?'Potential duplicate detected':'No high-similarity match detected').'</h2><p>Photo dated '.e($ev['evidence_date']).' · Uploaded '.e($ev['uploaded_at']).'</p><div class="similarity '.($flag?'similarity-alert':'similarity-safe').'"><span>Highest recorded similarity</span><strong>'.number_format((float)$ev['max_similarity'],1).'%</strong><small>'.($flag?'Review the original before approving.':'A distinct-looking image still needs your approval.').'</small></div>';
        if($flag && $ev['matched_evidence_id']) echo '<p>Compare with earlier submission <a class="text-link" href="image.php?id='.(int)$ev['matched_evidence_id'].'" target="_blank" rel="noopener">#'.(int)$ev['matched_evidence_id'].' (open photo)</a>.</p>';
        echo '<form method="post" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="evidence_decision"><input type="hidden" name="evidence_id" value="'.(int)$ev['id'].'"><div class="field"><label>Review notes '.($flag?'(required to approve a possible duplicate)':'(optional)').'</label><textarea name="review_note" rows="2" maxlength="500" placeholder="Describe your decision"></textarea></div><div class="review-actions"><button class="btn" type="submit" name="decision" value="approved">'.($flag?'Approve with justification':'Approve & associate').'</button><button class="btn btn-danger" type="submit" name="decision" value="rejected">Reject evidence</button></div></form></div></article>';
    }
    echo '<div class="content-card"><div class="section-heading"><h2>Recent review decisions</h2></div>';
    if(!$history) echo '<p class="muted">No reviewed submissions yet.</p>';else {echo '<div class="table-wrap"><table><thead><tr><th>Photo</th><th>Project / activity</th><th>Review</th><th>Similarity</th></tr></thead><tbody>'; foreach($history as $ev) echo '<tr><td><a class="text-link" href="image.php?id='.(int)$ev['id'].'" target="_blank">View image</a></td><td>'.e($ev['project_title']).'<span class="table-sub">'.e($ev['activity_title']).'</span></td><td>'.status_badge($ev['review_status']).'</td><td>'.number_format((float)$ev['max_similarity'],1).'%</td></tr>';echo '</tbody></table></div>'; }echo '</div>';page_end(true);
